// Compound component: Breadcrumb (the trail/list) + BreadcrumbItem (each crumb).
// Behavior borrowed from React Aria (Breadcrumbs/Breadcrumb, aliased); look owned via
// the .sd-breadcrumb BEM namespace + Cmp tokens. Named <Parent>/<Parent>Item to match
// this DS's compound convention (Select/SelectItem, Menu/MenuItem, …) + shadcn, even
// though React Aria itself names them Breadcrumbs/Breadcrumb.
import {
  Breadcrumb as AriaBreadcrumb,
  Breadcrumbs as AriaBreadcrumbs,
  Link as AriaLink,
} from "react-aria-components";
import type {
  BreadcrumbProps as AriaBreadcrumbProps,
  BreadcrumbsProps as AriaBreadcrumbsProps,
} from "react-aria-components";
import { ChevronRight } from "./icons";
import type { ReactNode, Ref } from "react";
import "./Breadcrumb.css";

export interface BreadcrumbProps<T extends object = object>
  extends Omit<AriaBreadcrumbsProps<T>, "className"> {
  /** Additional class (optional). sd-breadcrumb is always preserved. */
  className?: string;
  /** Forwarded to the underlying <ol> DOM node. */
  ref?: Ref<HTMLOListElement>;
}

export function Breadcrumb<T extends object = object>({
  className,
  isDisabled,
  ...props
}: BreadcrumbProps<T>) {
  return (
    <AriaBreadcrumbs
      {...props}
      isDisabled={isDisabled}
      // RAC marks items data-disabled but never the root <ol>; relay it so the
      // whole trail (incl. the current crumb) dims when the group is disabled.
      data-disabled={isDisabled || undefined}
      className={
        className
          ? `sd-breadcrumb sd-type-label-medium ${className}`
          : "sd-breadcrumb sd-type-label-medium"
      }
    />
  );
}

/** Common BreadcrumbItem props — axes independent of whether an accessible name is required. */
export interface BreadcrumbItemBaseProps
  extends Omit<AriaBreadcrumbProps, "className" | "children"> {
  /** Optional leading icon. It appears before the link/label. The `.sd-breadcrumb__icon` slot owns
      alignment and aria-hidden, and the slot font-size (16px) determines the size, so pass the icon
      with `size="1em"` (for example, `<House2 size="1em" />`). */
  icon?: ReactNode;
  /** Navigation destination. Without one or `onPress`, renders as current-location text. */
  href?: string;
  /** What a press does instead of navigating, for a trail inside an app (a selection's path in an
   *  editor) rather than across pages. A crumb with it is a link like one with `href`. */
  onPress?: () => void;
  /** Item content. */
  children?: ReactNode;
  /** Accessible name — required for an icon-only item with no visible text. */
  "aria-label"?: string;
  /** Supplies the accessible name by reference. Used instead of `aria-label`. */
  "aria-labelledby"?: string;
  /** Additional class (optional). sd-breadcrumb__item is always preserved. */
  className?: string;
  /** Forwarded to the underlying <li> DOM node. */
  ref?: Ref<HTMLLIElement>;
}

/**
 * BreadcrumbItem props.
 *
 * Because an icon-only item's `icon` is `aria-hidden` and it has no visible text, an accessible
 * name is **required at the type level** — one of `children` · `aria-label` · `aria-labelledby`
 * must be passed for it to compile (WCAG 4.1.2). The same shape as Button's `isIconOnly`
 * (component-contract.md §2 conditional requirement).
 */
export type BreadcrumbItemProps = BreadcrumbItemBaseProps &
  (
    | { children: ReactNode }
    | { "aria-label": string }
    | { "aria-labelledby": string }
  );

export function BreadcrumbItem({
  icon,
  href,
  onPress,
  children,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  className,
  ...props
}: BreadcrumbItemProps) {
  return (
    <AriaBreadcrumb
      {...props}
      // The name stays on the <li> as well, because the CURRENT crumb renders a plain <span>
      // (ARIA role=generic), where a name is *prohibited* — for that branch the listitem is the
      // only element that can carry one. RAC's filterDOMProps already put it here; the link
      // below is the addition.
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledBy}
      className={className ? `sd-breadcrumb__item ${className}` : "sd-breadcrumb__item"}
    >
      {({ isCurrent }) => (
        <>
          {(href || onPress) && !isCurrent ? (
            <AriaLink
              // The key is left out, not set to undefined: React Aria copies `href` into the DOM
              // whenever the key is present (`'href' in props`), so an onPress-only crumb rendered
              // its <span> with `href=""`.
              {...(href !== undefined && { href })}
              onPress={onPress}
              className="sd-breadcrumb__link sd-type-label-medium"
              // RAC's Breadcrumb supplies the nested Link only aria-current / isDisabled /
              // onPress through LinkContext (Breadcrumbs.mjs), and spreads its own labelling
              // props onto the <li> — so an inherited aria-label never reaches the <a>. Without
              // this an icon-only crumb ships an unnamed link (WCAG 4.1.2).
              aria-label={ariaLabel}
              aria-labelledby={ariaLabelledBy}
            >
              {icon && <span className="sd-breadcrumb__icon" aria-hidden="true">{icon}</span>}
              {children}
            </AriaLink>
          ) : (
            <span className="sd-breadcrumb__link sd-type-label-medium">
              {icon && <span className="sd-breadcrumb__icon" aria-hidden="true">{icon}</span>}
              {children}
            </span>
          )}
          <span
            aria-hidden="true"
            className="sd-breadcrumb__separator"
            data-current={isCurrent || undefined}
          >
            <ChevronRight aria-hidden size="1em" />
          </span>
        </>
      )}
    </AriaBreadcrumb>
  );
}

/* Breadcrumbs (compound: Breadcrumbs list + Breadcrumb item) — one BEM namespace.
   Item + its sub-parts (link, separator) are flat parts under the parent block. */
.sd-breadcrumb {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--sd-breadcrumb-gap);
  margin: 0;
  padding: 0;
  list-style: none;
}
.sd-breadcrumb[data-disabled] {
  opacity: var(--sd-state-disabled);
}

.sd-breadcrumb__item {
  display: inline-flex;
  align-items: center;
  gap: var(--sd-breadcrumb-item-gap);
  color: var(--sd-breadcrumb-item-foreground);
}
.sd-breadcrumb__item[data-current] {
  color: var(--sd-breadcrumb-item-foreground-current);
}

.sd-breadcrumb__link {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: var(--sd-breadcrumb-link-gap);
  padding-block: var(--sd-breadcrumb-link-padding-block);
  /* No inline padding of its own: the role class stands the label one text inset in (ADR-0053), and
     the state layer and ring bleed past the box by the overhang (component-contract.md §6 rule 8). */
  border-radius: var(--sd-breadcrumb-link-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  color: inherit;
  background: transparent;
  text-decoration: none;
  outline: none;
}
/* Interaction state-layer overlay (ADR-0009); color change stays on the link. It reaches past the
   box by the overhang inline, so the wash rounds away from a label that sits flush. */
.sd-breadcrumb__link::after {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline: calc(-1 * var(--sd-breadcrumb-link-state-layer-overhang));
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
/* hover = state-layer overlay only; link text stays the default color (like Button). */
.sd-breadcrumb__link[data-hovered]::after {
  background: var(--sd-state-hover);
}
/* pressed = state-layer overlay only; link text stays default (like ListBox items). */
.sd-breadcrumb__link[data-pressed]::after {
  background: var(--sd-state-pressed);
}
/* The ring traces the same bled shape the wash does, so the two indicators agree on where the link
   ends; the transparent outline rides along for forced colours. */
.sd-breadcrumb__link[data-focus-visible]::after {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

/* leading icon slot — sized to the icon token; inherits the crumb's text color. */
.sd-breadcrumb__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 var(--sd-breadcrumb-icon-size);
  width: var(--sd-breadcrumb-icon-size);
  height: var(--sd-breadcrumb-icon-size);
  font-size: var(--sd-breadcrumb-icon-size);
}

.sd-breadcrumb__separator {
  display: inline-flex;
  align-items: center;
  color: var(--sd-breadcrumb-separator-foreground);
}
.sd-breadcrumb__separator:dir(rtl) {
  scale: -1 1;
}
.sd-breadcrumb__separator[data-current] {
  display: none;
}
